-- V110__seed_cetrogar.sql — Cetrogar, VTEX: seed plus the curated leaf mapping.
--
-- Cetrogar (www.cetrogar.com.ar), appliances, electronics and furniture retailer on VTEX. Measured 2026-11-19 (legacy API, header `resources`):
-- 6270 products, 6033 in a real scrape (171 s). Mixed: rubro_forzado stays NULL (RubroResolver decides by category: appliances and furniture are
-- hogar, phones and TVs tecnologia) and rubro_por_defecto = 'tecnologia' for what no category decides (177 rows: helmets, satellite internet,
-- nebulizers, blood-pressure monitors).
-- One test product ("GEO SIMULATION PRODUCT", $1000) sits under the Garantias node: ServicioPorNombreDeCategoria excludes Garantias and its warranty
-- children, so it never reaches the database.
--
-- Leaf mapping: no new categories. The curated leaf outranks the name (NormalizerService.SITIOS_DONDE_LA_HOJA_GANA). Each leaf takes the category that
-- dominates it (>= 60% of its rows after the name classifier) except where curated by hand: phones and their accessories Celular, Arredo textiles sold
-- here (Almohadones, Acolchados) Almohadon / Ropa de Cama, hair, shaving and massage devices, juicers and sewing machines Pequeño Electrodoméstico,
-- toaster ovens Cocina y Horno, TV accessories and projectors TV y Audio, sommier bases Cama. Left unmapped (the name decides): Accesorios para PC
-- and gaming Accesorios (cases, mice, pads and controllers share one leaf), Indumentaria (brand merchandise), Cascos, Internet Satelital.
-- One single-line text blob (sitio_key|origen_id|nombre|categoria rows joined by ';', no raw newline: Sonar flags one inside a literal) split by the INSERT, not a literal per row: a string repeated
-- three times is Sonar S1192, and a long VALUES list of near-identical tuples is what Sonar CPD reads as duplicated code.
INSERT INTO sitio (nombre, sitio_key, plataforma, es_premium, rubro_forzado, origen) VALUES
    ('Cetrogar', 'cetrogar', 'vtex', false, NULL, 'config')
ON CONFLICT (nombre) DO NOTHING;

UPDATE sitio SET rubro_por_defecto = 'tecnologia' WHERE nombre = 'Cetrogar';

